-- PORTFOLIO-ONE-OWNER-2 (2026-10-19, pillar autonomy; issue 3009 PORTFOLIO-LOOP-DUPLICATION-1, reopened 2026-10-19T14:01Z by REMEDIATION-REOPEN-2)
--
-- WHAT HAPPENED: PORTFOLIO-ONE-OWNER-1 (migration_runs 297, 2026-10-18T13:15:03Z) cut fleet_tasks portfolio-lifecycle from 14 steps to 8 so the
-- lifecycle cron stopped filing issues the autopilot already files from the same gaps. Then migrations/2026-10-18-portfolio-lifecycle.sql was EDITED
-- and the runner re-applied it (migration_runs 309, 2026-10-18T14:44:14Z, a new sha256 of the same file): its INSERT OR REPLACE INTO fleet_tasks wrote
-- the 14-step definition back over the 8-step one, and its backfill statements file PORTFOLIO-IMPLEMENT-1 and PORTFOLIO-DEPLOY-RECORD-1 issues again.
-- Measured 2026-10-19T14:03Z: json_array_length(definition, '$.steps') = 14, version 1, updated_at 2026-10-18 14:44:00. The issue-3009 contract probe
-- (expects 8 steps) failed max_attempts times and the D1 trigger reopened the issue, correctly.
--
-- WHAT THIS FILE DOES: re-asserts the 8-step definition (the statement is the one in 2026-10-18-portfolio-one-owner.sql, verbatim). The cause is
-- removed in the same change: 2026-10-18-portfolio-lifecycle.sql now writes its fleet_tasks row with INSERT OR IGNORE and no longer carries the
-- issue-filing backfill, so a re-application can no longer undo the one-owner state; and scripts/apply_migrations.py --check --base refuses an
-- edited, already-merged migration that rewrites a live definition row (MIGRATION-NO-CLOBBER-1) unless it carries a REAPPLY-OK line.
--
-- Revert: INSERT OR REPLACE the 14-step row from migrations/2026-10-18-portfolio-lifecycle.sql history (git show 8e6638e^:...); the cron name and
-- schedule are untouched here.
--
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: restore the 14-step definition of fleet_tasks portfolio-lifecycle from the version of migrations/2026-10-18-portfolio-lifecycle.sql before PORTFOLIO-ONE-OWNER-2.

INSERT OR REPLACE INTO fleet_tasks (id, name, type, definition, timeout_ms, retries, version, enabled, updated_at)
VALUES ('portfolio-lifecycle', 'PORTFOLIO-LIFECYCLE-1: record portfolio facts (deploys, state, phases, freshness, gaps); the autopilot owns filing from gaps (PORTFOLIO-ONE-OWNER-1)',
  'workflow', '{"steps":[{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO phases (phase_code, project_code, phase_number, name, description, status) SELECT ''P1-''||p.project_code, p.project_code, 1, ''Operate and verify'', ''auto (PORTFOLIO-LIFECYCLE-1): the project had no phase, so v_project_health could not report progress. Done when its owning worker answers /health and its newest linked deploy is younger than 30 days.'', CASE WHEN p.status=''completed'' THEN ''completed'' ELSE ''in_progress'' END FROM projects p WHERE NOT EXISTS (SELECT 1 FROM phases ph WHERE ph.project_code=p.project_code)"},{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO project_ledger (project_id, session_id, phase, task_id, action, evidence, worker_name, timestamp) SELECT p.project_code, ''portfolio-lifecycle'', COALESCE((SELECT MAX(ph.phase_number) FROM phases ph WHERE ph.project_code=p.project_code),1), ''deploy:''||dh.id, ''deployed'', ''version ''||COALESCE(dh.version_id,''?'')||'' deployed by ''||COALESCE(dh.deployed_by,''?''), dh.resource_name, COALESCE(dh.deployed_at, datetime(''now'')) FROM deployment_history dh JOIN projects p ON p.project_code=''W.''||dh.resource_name WHERE dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'' AND replace(substr(COALESCE(dh.deployed_at,''''),1,19),''T'','' '') >= datetime(''now'',''-7 days'') AND NOT EXISTS (SELECT 1 FROM project_ledger l WHERE l.task_id=''deploy:''||dh.id) ORDER BY dh.id DESC LIMIT 400"},{"type":"sql","db":"AUDIT","sql":"INSERT INTO project_state (project_code, session_id, current_phase, phase_progress, resource_counts, git_commit) SELECT l.project_id, l.task_id, l.phase, 1.0, json_object(''worker'', dh.resource_name, ''version'', dh.version_id, ''deployed_at'', dh.deployed_at, ''deployed_by'', dh.deployed_by), NULL FROM project_ledger l JOIN deployment_history dh ON l.task_id=''deploy:''||dh.id WHERE l.action=''deployed'' AND NOT EXISTS (SELECT 1 FROM project_state s WHERE s.project_code=l.project_id AND s.session_id=l.task_id) ORDER BY l.id ASC LIMIT 400"},{"type":"sql","db":"AUDIT","sql":"UPDATE projects SET updated_at = (SELECT MAX(replace(substr(dh.deployed_at,1,19),''T'','' '')) FROM deployment_history dh WHERE dh.resource_name=projects.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'') WHERE EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=projects.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'' AND replace(substr(dh.deployed_at,1,19),''T'','' '') > COALESCE(projects.updated_at,''''))"},{"type":"sql","db":"AUDIT","sql":"UPDATE programs SET updated_at=datetime(''now'') WHERE program_code IN (SELECT DISTINCT program_code FROM projects WHERE updated_at >= datetime(''now'',''-1 day''))"},{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO portfolio_gaps (kind, entity, detail, day) SELECT ''project-stale-deploy'', p.project_code, ''active project whose owner last deployed ''||COALESCE((SELECT MAX(dh.deployed_at) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success''),''never''), date(''now'') FROM projects p WHERE p.status=''active'' AND p.owner_service IS NOT NULL AND COALESCE((SELECT MAX(replace(substr(dh.deployed_at,1,19),''T'','' '')) FROM deployment_history dh WHERE dh.resource_name=p.owner_service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success''),''1970-01-01'') < datetime(''now'',''-30 days'')"},{"type":"sql","db":"AUDIT","sql":"INSERT OR IGNORE INTO portfolio_gaps (kind, entity, detail, day) SELECT ''deploy-unrecorded'', s.service, ''live worker ''||s.service||'' has no successful deploy in deployment_history, so its project cannot show what it runs'', date(''now'') FROM service_registry s WHERE s.kind=''worker'' AND s.state=''live'' AND NOT EXISTS (SELECT 1 FROM deployment_history dh WHERE dh.resource_name=s.service AND dh.action=''deploy'' AND COALESCE(dh.status,''success'')=''success'')"},{"type":"sql","db":"AUDIT","sql":"INSERT OR REPLACE INTO cloud_ops_events (id, ts, kind, text, meta, job, status) SELECT ''portfolio-lifecycle-''||strftime(''%Y%m%d%H%M%S'',''now''), datetime(''now''), ''portfolio-lifecycle'', ''PORTFOLIO-LIFECYCLE-1: ''||(SELECT COUNT(*) FROM project_ledger WHERE action=''deployed'')||'' linked deploys over '' ||(SELECT COUNT(DISTINCT project_id) FROM project_ledger WHERE action=''deployed'')||'' projects | '' ||(SELECT COUNT(*) FROM projects WHERE status=''active'' AND NOT EXISTS (SELECT 1 FROM phases ph WHERE ph.project_code=projects.project_code))||'' active projects without a phase | '' ||(SELECT COUNT(*) FROM agent_issues WHERE source=''portfolio-lifecycle'' AND status=''open'')||'' open portfolio issues'', NULL, ''portfolio-lifecycle'', ''ok''"}]}', 120000, 1, 2, 1, datetime('now'));

INSERT OR IGNORE INTO failure_modes (fm_key, failure_mode, root_cause, remediation, detector, probe_class, first_seen, issue_id, trigger_condition, symptom, blast_radius)
VALUES ('migration-reapply-clobber',
  'an edited migration that already merged is applied again and overwrites a newer definition of a live fleet_tasks, fleet_crons or ops_config row',
  'scripts/apply_migrations.py applies a file again whenever its sha256 changes, so any edit to a merged file re-runs all of it; 2026-10-18-portfolio-lifecycle.sql was edited two hours after PORTFOLIO-ONE-OWNER-1 and its INSERT OR REPLACE put the 14-step portfolio-lifecycle definition back over the 8-step one (migration_runs 309, 14:44:14Z), reopening issue 3009 a day later',
  'MIGRATION-NO-CLOBBER-1: scripts/apply_migrations.py --check --base <ref> (the deploy-gate step) refuses an edited, already-merged APPLY-BY: ci file whose statements rewrite fleet_tasks, fleet_crons or ops_config unless it carries a REAPPLY-OK line with a reason; the portfolio-lifecycle file now writes its row with INSERT OR IGNORE and carries REAPPLY-OK; this file restores the 8-step definition',
  'scripts/apply_migrations.py on main defines clobber_problems and the deploy-gate migration step passes --base (code-read contract fm-migration-reapply-clobber)',
  'fm-migration-reapply-clobber', '2026-10-19', 3009,
  'a PR that edits a migration which is already in migration_runs ok and contains INSERT OR REPLACE INTO fleet_tasks, UPDATE fleet_crons or UPDATE ops_config',
  'a live definition row reads an older version than the newest migration that wrote it; an issue whose contract probe reads that definition reopens',
  'any fleet_tasks workflow, cron schedule or ops_config switch a merged migration defined');

